begin;

delete from public.version_banners vb
using public.game_versions gv, public.games g
where vb.version_id=gv.id and gv.game_id=g.id and g.code='YYS'
  and gv.version_no between 'YYS-2019-01-01' and 'YYS-2021-12-31';

with yys as (select id from public.games where code='YYS' limit 1),payload as (select $json$[{"version_no":"YYS-2019-01-30","version_name":"双神降临","start_date":"2019-01-30","note":"新春双SP版本。","banners":[{"character":"苍风一目连","banner_type":"pickup"},{"character":"稻荷神御馔津","banner_type":"pickup"},{"character":"化鲸","banner_type":"standard_addition"}]},{"version_no":"YYS-2019-03-20","version_name":"赤影刀舞","start_date":"2019-03-20","note":"","banners":[{"character":"赤影妖刀姬","banner_type":"pickup"}]},{"version_no":"YYS-2019-04-29","version_name":"离岛之歌","start_date":"2019-04-29","note":"不知火主题大型版本。","banners":[{"character":"不知火","banner_type":"pickup"}]},{"version_no":"YYS-2019-05-29","version_name":"历史更新｜御怨般若登场","start_date":"2019-05-29","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"御怨般若","banner_type":"pickup"},{"character":"海忍","banner_type":"standard_addition"}]},{"version_no":"YYS-2019-06-26","version_name":"海国篇｜大岳丸登场","start_date":"2019-06-26","note":"海国主线阶段性大型内容更新。","banners":[{"character":"大岳丸","banner_type":"pickup"},{"character":"久次良","banner_type":"standard_addition"}]},{"version_no":"YYS-2019-07-31","version_name":"历史更新｜骁浪荒川之主登场","start_date":"2019-07-31","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"骁浪荒川之主","banner_type":"pickup"},{"character":"蟹姬","banner_type":"standard_addition"}]},{"version_no":"YYS-2019-08-21","version_name":"BLEACH联动·第一弹","start_date":"2019-08-21","note":"《BLEACH境·界》联动。","banners":[{"character":"黑崎一护","banner_type":"collab"},{"character":"朽木露琪亚","banner_type":"collab"}]},{"version_no":"YYS-2019-09-20","version_name":"三周年庆典版本","start_date":"2019-09-20","note":"国服三周年核心内容更新。","banners":[{"character":"泷夜叉姬","banner_type":"pickup"},{"character":"烬天玉藻前","banner_type":"pickup"}]},{"version_no":"YYS-2019-10-23","version_name":"历史更新｜纸舞登场","start_date":"2019-10-23","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"纸舞","banner_type":"standard_addition"}]},{"version_no":"YYS-2019-10-30","version_name":"大江山之战·鬼王重归","start_date":"2019-10-30","note":"","banners":[{"character":"鬼王酒吞童子","banner_type":"pickup"},{"character":"星熊童子","banner_type":"standard_addition"}]},{"version_no":"YYS-2019-11-27","version_name":"灼锋淬火·百炼韧心","start_date":"2019-11-27","note":"","banners":[{"character":"天剑韧心鬼切","banner_type":"pickup"}]},{"version_no":"YYS-2019-12-25","version_name":"镜之卷","start_date":"2019-12-25","note":"云外镜主题内容更新。","banners":[{"character":"云外镜","banner_type":"pickup"}]},{"version_no":"YYS-2020-01-20","version_name":"鬼域修罗·新春版本","start_date":"2020-01-20","note":"","banners":[{"character":"鬼童丸","banner_type":"pickup"},{"character":"聆海金鱼姬","banner_type":"pickup"}]},{"version_no":"YYS-2020-03-11","version_name":"缘结京都","start_date":"2020-03-11","note":"缘结神主题版本；同期核心召唤活动为「缘结京都·神赐良缘」。","banners":[{"character":"缘结神","banner_type":"pickup"}]},{"version_no":"YYS-2020-04-15","version_name":"百鬼夜话","start_date":"2020-04-15","note":"","banners":[{"character":"浮世青行灯","banner_type":"pickup"}]},{"version_no":"YYS-2020-04-29","version_name":"历史更新｜风狸登场","start_date":"2020-04-29","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"风狸","banner_type":"standard_addition"}]},{"version_no":"YYS-2020-05-20","version_name":"鬼王之宴","start_date":"2020-05-20","note":"","banners":[{"character":"铃鹿御前","banner_type":"pickup"}]},{"version_no":"YYS-2020-06-10","version_name":"历史更新｜蝎女登场","start_date":"2020-06-10","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"蝎女","banner_type":"standard_addition"}]},{"version_no":"YYS-2020-06-24","version_name":"蛇骨缚心","start_date":"2020-06-24","note":"","banners":[{"character":"缚骨清姬","banner_type":"pickup"}]},{"version_no":"YYS-2020-07-29","version_name":"雅乐之邦","start_date":"2020-07-29","note":"","banners":[{"character":"紧那罗","banner_type":"pickup"}]},{"version_no":"YYS-2020-09-23","version_name":"四周年·麓海归途","start_date":"2020-09-23","note":"国服四周年大型版本。","banners":[{"character":"麓铭大岳丸","banner_type":"pickup"},{"character":"待宵姑获鸟","banner_type":"pickup"}]},{"version_no":"YYS-2020-10-28","version_name":"永生之海","start_date":"2020-10-28","note":"","banners":[{"character":"千姬","banner_type":"pickup"}]},{"version_no":"YYS-2020-12-02","version_name":"风起之森","start_date":"2020-12-02","note":"","banners":[{"character":"初翎山风","banner_type":"pickup"}]},{"version_no":"YYS-2021-01-06","version_name":"彼世之花","start_date":"2021-01-06","note":"","banners":[{"character":"夜溟彼岸花","banner_type":"pickup"}]},{"version_no":"YYS-2021-02-07","version_name":"鬼灭之刃联动·第一弹","start_date":"2021-02-07","note":"《鬼灭之刃》联动第一弹。","banners":[{"character":"灶门炭治郎","banner_type":"collab"},{"character":"灶门祢豆子","banner_type":"collab"},{"character":"垢尝","banner_type":"standard_addition"}]},{"version_no":"YYS-2021-03-17","version_name":"雪落樱祭","start_date":"2021-03-17","note":"","banners":[{"character":"蝉冰雪女","banner_type":"pickup"}]},{"version_no":"YYS-2021-03-31","version_name":"历史更新｜呱太扩充","start_date":"2021-03-31","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"御馔津呱","banner_type":"standard_addition"},{"character":"雪童子呱","banner_type":"standard_addition"},{"character":"玉藻前呱","banner_type":"standard_addition"}]},{"version_no":"YYS-2021-04-21","version_name":"红莲华冕","start_date":"2021-04-21","note":"天域篇·上核心版本。","banners":[{"character":"帝释天","banner_type":"pickup"}]},{"version_no":"YYS-2021-05-26","version_name":"天魔归来","start_date":"2021-05-26","note":"","banners":[{"character":"阿修罗","banner_type":"pickup"}]},{"version_no":"YYS-2021-06-09","version_name":"永生之海御魂副本","start_date":"2021-06-09","note":"永久系统型大型更新：开放永生之海御魂副本并加入新御魂套装。","banners":[]},{"version_no":"YYS-2021-06-23","version_name":"青森之秘","start_date":"2021-06-23","note":"","banners":[{"character":"入内雀","banner_type":"standard_addition"}]},{"version_no":"YYS-2021-07-21","version_name":"罪业回舞","start_date":"2021-07-21","note":"","banners":[{"character":"空相面灵气","banner_type":"pickup"}]},{"version_no":"YYS-2021-08-25","version_name":"妙笔绘世","start_date":"2021-08-25","note":"","banners":[{"character":"绘世花鸟卷","banner_type":"pickup"}]},{"version_no":"YYS-2021-09-15","version_name":"历史更新｜饴细工登场","start_date":"2021-09-15","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"饴细工","banner_type":"standard_addition"}]},{"version_no":"YYS-2021-09-23","version_name":"五周年·真味如初","start_date":"2021-09-23","note":"国服五周年大型版本。","banners":[{"character":"食灵","banner_type":"pickup"},{"character":"饭笥","banner_type":"pickup"}]},{"version_no":"YYS-2021-11-10","version_name":"历史更新｜川猿登场","start_date":"2021-11-10","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"川猿","banner_type":"standard_addition"}]},{"version_no":"YYS-2021-11-24","version_name":"真实之羽","start_date":"2021-11-24","note":"","banners":[{"character":"因幡辉夜姬","banner_type":"pickup"}]},{"version_no":"YYS-2021-12-29","version_name":"赤月谜影·绮世物语","start_date":"2021-12-29","note":"京极夏彦艺术灵感企划「绮世物语」阶段内容，夜刀神登场；鬼灭联动角色同期返场。","banners":[{"character":"夜刀神","banner_type":"collab"},{"character":"灶门炭治郎","banner_type":"rerun"},{"character":"灶门祢豆子","banner_type":"rerun"}]}]$json$::jsonb data),
vr as(select x from payload cross join lateral jsonb_array_elements(data)x),
upserted as (
 insert into public.game_versions(game_id,version_no,version_name,start_date,note)
 select yys.id,x->>'version_no',x->>'version_name',(x->>'start_date')::date,nullif(x->>'note','') from yys cross join vr
 on conflict(game_id,version_no) do update set version_name=excluded.version_name,start_date=excluded.start_date,note=excluded.note,updated_at=now()
 returning id,version_no
),
br as(select x->>'version_no' version_no,b from vr cross join lateral jsonb_array_elements(coalesce(x->'banners','[]'::jsonb))b)
insert into public.version_banners(version_id,phase,banner_type,character_id,character_name_raw)
select u.id,case when br.b->>'banner_type'='standard_addition' then 'standard' else 'other' end,br.b->>'banner_type',c.id,br.b->>'character'
from br join upserted u using(version_no)
left join public.characters c on c.game_id=(select id from yys) and c.name=br.b->>'character';

commit;
